318: function updateSimulation(dt) {
319:   const gm = dt * 1.15;
320:   state.time.minutes += gm;
321:   while (state.time.minutes >= 1440) {
322:     state.time.minutes -= 1440;
323:     state.time.day++;
324:     state.stats.days++;
325:     state.player.rentDue = Math.max(0, (state.player.rentDue || 0) - 1);
326:     if (state.player.rentDue === 0 && !state.player.homeOwned) {
327:       ui.toast('<b>LANDLORD</b> · Rent is due. $650. The door still opens. For now.', 'warn');
328:     }
329:     ui.toast(`<b>DAY ${state.time.day + 1}</b> · ${['MON','TUE','WED','THU','FRI','SAT','SUN'][state.time.day % 7]} in Bellingham.`, '');
330:   }
331:   const p = state.player;
332:   p.hunger = clamp(p.hunger - gm * .024, 0, 100);
333:   p.energy = clamp(p.energy - gm * .012, 0, 100);
334:   p.hygiene = clamp(p.hygiene - gm * .009, 0, 100);
335:   p.mood = clamp(p.mood - gm * .006 - (p.hunger < 20 ? gm * .01 : 0), 0, 100);
336:   p.intoxication = clamp((p.intoxication || 0) - gm * .08, 0, 100);
337:   p.heat = clamp((p.heat || 0) - gm * .004, 0, 100);
338:   if (p.hunger > 35 && p.energy > 30 && p.health < 100) p.health = clamp(p.health + gm * .008, 0, 100);
339:   if (p.intoxication > 0) p.mood = clamp(p.mood + gm * .004, 0, 100);
340:   const warns = [['hunger',22,'You are starving. Eat something.'],['energy',18,'Your eyes are closing. Sleep.'],['hygiene',16,'You smell like the bay.'],['mood',15,'The city is getting under your skin.']];
341:   for (const [key, thresh, text] of warns) {
342:     if (p[key] < thresh && performance.now() - (toastWarned[key] || 0) > 60000) {
343:       toastWarned[key] = performance.now();
344:       ui.toast('<b>NEED</b> · ' + text, 'warn');
345:     }
346:   }
347:   const d = world.districtAt(player.x, player.z);
348:   if (d.id !== lastArea) {
349:     lastArea = d.id;
350:     ui.showArea(d.name, d.sub);
351:   }
352: }
