354: function updateWeather(dt) {
355:   weatherTimer -= dt;
356:   if (weatherTimer > 0) return;
357:   weatherTimer = 95 + Math.random() * 130;
358:   if (state.quest.stage === 4 && !state.flags.raincoatFound) {
359:     if (world.weather !== 'storm') { setWeather('storm'); ui.showEvent('BAROMETRIC FAILURE','The forecast says rain. The sky says something else.'); }
360:     return;
361:   }
362:   const keys = ['rain','rain','heavy','fog','overcast','clear'];
363:   if (state.weirdness > .6) keys.push('storm','storm');
364:   const next = keys[Math.floor(Math.random() * keys.length)];
365:   if (next !== world.weather) {
366:     setWeather(next);
367:     if (next === 'storm') {
368:       state.stats.storms++;
369:       ui.showEvent('ELECTRIC STORM','The lights flicker in a rhythm. It might be a heartbeat.');
370:       audio.thunder();
371:     } else {
372:       ui.toast(`<b>WEATHER</b> · ${WEATHER[next].label}.`, '');
373:     }
374:   }
375: }
