670: function greetingFor(npc) {
671:   const r = relOf(npc);
672:   const weird = state.weirdness || .1;
673:   if (!r.met) {
674:     r.met = true;
675:     return npcLine(npc, 'intro') || npc.intro || `${npc.name} looks at you like they have seen you somewhere before.`;
676:   }
677:   if (r.fights > 0) {
678:     return r.wins > 0
679:       ? `“Still standing,” ${npc.name.split(' ')[0]} says. “That’s not nothing.”`
680:       : `“You heal fast,” ${npc.name.split(' ')[0]} says. “Most people don’t come back after a night like that.”`;
681:   }
682:   if (weird > .72 && Math.random() < .38) return npcLine(npc, 'weird') || 'They say your name before you tell them. Then they smile like it was a joke.';
683:   if (r.romance >= 55) return ['They lean against the nearest wall like it was built for this.', 'Their hand finds yours. The rain gets louder.', 'You get the smile they keep for after midnight.'][Math.floor(Math.random()*3)];
684:   if (r.grudge >= 25) return 'They look at you the way you look at a bruise.';
685:   if (r.affinity >= 25) return `“Hey, ${state.player.name.split(' ')[0]}.” They say it like it’s a small gift.`;
686:   if (r.affinity >= 8) return 'They nod. The city keeps moving around you both.';
687:   return ['“Yeah?”', 'They give you the half-second version of a smile.', '“You need something?”'][Math.floor(Math.random()*3)];
688: }
