690: function talkTo(npc) {
691:   if (!npc) return;
692:   if (player.driving) player.exitCar();
693:   gameMode = 'dialogue';
694:   player.moveInput(0, 0);
695:   const r = relOf(npc);
696:   r.lastTalk = state.time.day * 1440 + state.time.minutes;
697:   const text = greetingFor(npc);
698:   ui.openDialogue(npc, text, choicesFor(npc), (ch) => dialogueChoice(npc, ch));
699:   audio.speak();
700: }
