702: function choicesFor(npc) {
703:   const r = relOf(npc);
704:   const ch = [{ id:'talk', label:'TALK' }, { id:'rain', label:'TALK ABOUT THE RAIN' }];
705:   ch.push({ id:'city', label:'ASK ABOUT THE CITY' });
706:   ch.push({ id:'rumor', label:'ASK ABOUT RUMORS' });
707:   if (r.met) ch.push({ id:'compliment', label:'COMPLIMENT' });
708:   if (npc.romanceable && (npc.age || 0) >= 18) {
709:     ch.push({ id:'flirt', label:'FLIRT' });
710:     if (r.affinity >= 20) ch.push({ id:'date', label:'ASK ON A DATE' });
711:     if (r.romance >= 35) ch.push({ id:'kiss', label:'KISS' });
712:     if (r.romance >= 60) ch.push({ id:'intimacy', label:'SPEND THE NIGHT', special:true });
713:   }
714:   if (state.inventory.some(i => ITEMS[i.id]?.type === 'gift')) ch.push({ id:'gift', label:'GIVE A GIFT' });
715:   if (npc.fighter) ch.push({ id:'spar', label:'SPAR' });
716:   const boss = bossFor(npc);
717:   if (boss && canChallengeBoss(boss.id)) ch.push({ id:'challenge', label:'CHALLENGE', special:true });
718:   if (npc.id === 'dax' && !state.flags.quietTable) ch.push({ id:'quiet', label:'LISTEN TO THE OFFER', special:true });
719:   ch.push({ id:'bye', label:'LEAVE' });
720:   return ch;
721: }
