723: function dialogueChoice(npc, ch) {
724:   const r = relOf(npc);
725:   const id = ch.id;
726:   audio.ui();
727:   if (id === 'bye') { closeDialogue(); return; }
728:   if (id === 'talk') {
729:     const text = r.affinity > 20
730:       ? ['“I was wondering when you’d come by.”', '“You’re becoming a regular. That’s either good or terminal.”', 'They tell you a small, true thing about their day.'][Math.floor(Math.random()*3)]
731:       : ['They talk about work, the weather, the price of everything.', 'The conversation is ordinary. It feels like a luxury.', '“Not much. Same rain. Same city. Different trouble.”'][Math.floor(Math.random()*3)];
732:     r.affinity = clamp(r.affinity + 2, 0, 100); r.trust = clamp(r.trust + 1, 0, 100);
733:     addMemory(npc, 'shared a quiet conversation');
734:     ui.updateDialogueText(text); refreshDialogueChoices(npc); return;
735:   }
736:   if (id === 'rain') {
737:     const text = npcLine(npc, 'weird') && state.weirdness > .35
738:       ? npcLine(npc, 'weird')
739:       : ['“It’s Bellingham. Rain is the local language.”', '“You get used to it. Then you get weird about it.”', '“I like the rain. It makes the city feel honest.”'][Math.floor(Math.random()*3)];
740:     r.affinity = clamp(r.affinity + 1, 0, 100);
741:     ui.updateDialogueText(text); refreshDialogueChoices(npc); return;
742:   }
743:   if (id === 'city') {
744:     ui.updateDialogueText(npcLine(npc, 'city') || '“It’s a city. It has opinions about itself.”');
745:     refreshDialogueChoices(npc); return;
746:   }
747:   if (id === 'rumor') {
748:     let text = npcLine(npc, 'rumor') || '“Rumors are just weather with better marketing.”';
749:     if (state.quest.stage >= 3) text += ' They glance at the nearest streetlight like it might be recording.';
750:     state.weirdness = clamp(state.weirdness + .004, 0, 1);
751:     world.setWeirdness(state.weirdness);
752:     ui.updateDialogueText(text); refreshDialogueChoices(npc); return;
753:   }
754:   if (id === 'compliment') {
755:     r.affinity = clamp(r.affinity + 5, 0, 100); r.mood = r.mood;
756:     state.player.mood = clamp(state.player.mood + 3, 0, 100);
757:     ui.updateDialogueText(['They try not to smile. They fail.', '“Careful. I’m susceptible to that.”', '“You’re not bad yourself. For someone who smells like the bay.”'][Math.floor(Math.random()*3)]);
758:     refreshDialogueChoices(npc); return;
759:   }
760:   if (id === 'flirt') {
761:     if ((npc.age || 0) < 18) { ui.updateDialogueText('They step back. “No.” The conversation is over.'); return; }
762:     if (r.affinity < 10) {
763:       ui.updateDialogueText('They give you a look that could refrigerate a beer. “Let’s not.”');
764:       r.grudge = clamp(r.grudge + 2, 0, 100);
765:     } else {
766:       r.romance = clamp(r.romance + 6, 0, 100); r.affinity = clamp(r.affinity + 4, 0, 100);
767:       r.status = statusFor(r); addMemory(npc, 'flirted and meant it');
768:       ui.updateDialogueText(['They hold your gaze a beat too long. “Smooth. Suspiciously smooth.”', '“You’re trouble,” they say, and do not move away.', 'The rain gets between you. Neither of you steps back.'][Math.floor(Math.random()*3)]);
769:     }
770:     refreshDialogueChoices(npc); return;
771:   }
772:   if (id === 'gift') {
773:     const gift = state.inventory.find(i => ITEMS[i.id]?.type === 'gift');
774:     if (!gift) { ui.updateDialogueText('You have nothing to give but the truth. They can tell.'); return; }
775:     removeItem(gift.id, 1);
776:     r.affinity = clamp(r.affinity + 12, 0, 100); r.romance = clamp(r.romance + 5, 0, 100); r.status = statusFor(r);
777:     addMemory(npc, `received ${ITEMS[gift.id].name}`);
778:     ui.updateDialogueText(`You give them the ${ITEMS[gift.id].name}. ${npc.name.split(' ')[0]} turns it over once, like it might be a key. “Oh.”`);
779:     refreshDialogueChoices(npc); return;
780:   }
781:   if (id === 'date') {
782:     if (r.affinity < 20) { ui.updateDialogueText('“Maybe when I know you better.”'); return; }
783:     r.dates++; r.romance = clamp(r.romance + 10, 0, 100); r.affinity = clamp(r.affinity + 8, 0, 100);
784:     r.status = statusFor(r); addMemory(npc, 'went on a date');
785:     state.player.mood = clamp(state.player.mood + 16, 0, 100);
786:     state.player.money = Math.max(0, state.player.money - 35);
787:     state.time.minutes += 150;
788:     state.player.energy = clamp(state.player.energy - 10, 0, 100);
789:     closeDialogue();
790:     gameMode = 'modal';
791:     ui.cinematic('A NIGHT OFF', 'THE CITY, BRIEFLY KIND', 'You eat something warm. You walk until the rain stops being an emergency. Neither of you checks your phone.');
792:     setTimeout(() => {
793:       ui.modal({
794:         kicker:'RELATIONSHIP', title:'A GOOD NIGHT',
795:         body:`<p>You and ${esc(npc.name)} spend two hours at ${['Boulevard Park','the marina','a noodle place that is somehow still open','the bookstore after hours'][Math.floor(Math.random()*4)]}. It is not cinematic. It is better.</p><p class="modal-quote">“Same time next week?” they ask.<br>You say yes before you can calculate anything.</p>`,
796:         actions:[{label:'CONTINUE', id:'ok', primary:true}],
797:         onAction:() => { ui.closeModal(); gameMode = 'play'; refreshDialogueChoices(npc); }
798:       });
799:     }, 1500);
800:     return;
801:   }
802:   if (id === 'kiss') {
803:     if (r.romance < 35) { ui.updateDialogueText('They turn their head at the last second. “Not yet.”'); return; }
804:     r.romance = clamp(r.romance + 7, 0, 100); r.affinity = clamp(r.affinity + 5, 0, 100); r.status = statusFor(r);
805:     state.player.mood = clamp(state.player.mood + 12, 0, 100); addMemory(npc, 'kissed in the rain');
806:     ui.updateDialogueText(['They kiss you like the city has stopped watching. For a second, it has.', '“Okay,” they breathe. “Okay.”', 'The rain does most of the work. They do the rest.'][Math.floor(Math.random()*3)]);
807:     refreshDialogueChoices(npc); return;
808:   }
809:   if (id === 'intimacy') {
810:     if (r.romance < 60) { ui.updateDialogueText('“I like you. I’m not there yet.”'); return; }
811:     closeDialogue();
812:     gameMode = 'modal';
813:     ui.modal({
814:       kicker:'CONSENT · ADULTS ONLY', title:'SPEND THE NIGHT?',
815:       body:`<p>${esc(npc.name)} asks if you want to come back to their place. You both agree, clearly, without pressure.</p><p class="modal-quote">The rest happens off-screen. This story fades to black.</p>`,
816:       actions:[{label:'YES, TONIGHT', id:'yes', primary:true}, {label:'NOT TONIGHT', id:'no'}],
817:       onAction:(a) => {
818:         ui.closeModal();
819:         if (a === 'no') { gameMode='play'; ui.toast('<b>BOUNDARY</b> · No pressure. The night stays yours.', ''); return; }
820:         r.romance = clamp(r.romance + 12, 0, 100); r.affinity = clamp(r.affinity + 10, 0, 100); r.status = statusFor(r);
821:         state.player.mood = clamp(state.player.mood + 25, 0, 100); state.player.energy = clamp(state.player.energy - 15, 0, 100);
822:         state.time.minutes += 390; addMemory(npc, 'spent the night together');
823:         gameMode = 'ending';
824:         (async () => {
825:           await ui.fade(true, 900);
826:           await new Promise(r => setTimeout(r, 900));
827:           ui.subtitle('The rest is yours. The city politely looks away.', 2500);
828:           await ui.fade(false, 900);
829:           gameMode = 'play';
830:           ui.toast(`<b>MORNING</b> · You wake up next to ${npc.name}. The rain has not stopped. It never does.`, '');
831:           checkJealousy(npc);
832:           saveGame(true);
833:         })();
834:       }
835:     });
836:     return;
837:   }
838:   if (id === 'spar') {
839:     closeDialogue();
840:     startFight(npc, null, { street:true });
841:     return;
842:   }
843:   if (id === 'challenge') {
844:     const boss = bossFor(npc);
845:     if (!boss) return;
846:     closeDialogue();
847:     if (boss.id === 'raincoat' && !state.flags.raincoatFound) {
848:       if (world.weather !== 'storm') { ui.toast('<b>NO STORM</b> · The raincoat is not here yet.', 'warn'); return; }
849:     }
850:     showBossIntro(boss, npc);
851:     return;
852:   }
853:   if (id === 'quiet') {
854:     r.affinity = clamp(r.affinity + 4, 0, 100); r.trust = clamp(r.trust + 2, 0, 100);
855:     closeDialogue();
856:     gameMode = 'modal';
857:     ui.modal({
858:       kicker:'THE QUIET TABLE', title:'A SEAT WITH NO NAME',
859:       body:`<p>Dax leans close enough that you can smell expensive cologne and bad intentions.</p><p class="modal-quote">“There’s a table under Terminal 9. They don’t bet money. They bet outcomes. You get a chair if you bring them something they can’t simulate.”</p><p>He taps the table twice. Somewhere, a door you have never seen unlocks.</p>`,
860:       actions:[{label:'TAKE THE SEAT · $250', id:'yes', primary:true}, {label:'WALK AWAY', id:'no'}],
861:       onAction:(a) => {
862:         ui.closeModal(); gameMode = 'play';
863:         if (a === 'no') { ui.toast('<b>DECLINED</b> · Dax shrugs. “Everyone says that first.”', ''); return; }
864:         if (state.player.money < 250) { ui.toast('<b>NO CASH</b> · Dax’s smile closes like a register.', 'warn'); return; }
865:         state.player.money -= 250; state.flags.quietTable = true; state.flags.darkRep = (state.flags.darkRep || 0) + 1;
866:         state.player.reputation = clamp(state.player.reputation + 20, -100, 1000);
867:         state.weirdness = clamp(state.weirdness + .08, 0, 1); world.setWeirdness(state.weirdness);
868:         ui.toast('<b>THE QUIET TABLE</b> · You have a seat. It is colder than it looks.', 'warn');
869:         saveGame(true);
870:       }
871:     });
872:     return;
873:   }
