1411: function setTimingTarget() {
1412:   if (!timingGame) return;
1413:   const t = .18 + Math.random() * .64;
1414:   timingGame.target = t;
1415:   const zone = $('timing-zone');
1416:   if (zone) { zone.style.left = (t * 100 - 7) + '%'; zone.style.width = '14%'; }
1417:   const r = $('timing-round');
1418:   if (r) r.textContent = `ROUND ${Math.min(timingGame.round + 1, timingGame.rounds)} / ${timingGame.rounds}`;
1419:   const s = $('timing-status');
1420:   if (s) { s.textContent = 'READY'; s.className = ''; }
1421: }
