702: function choicesFor(npc) {
703:   const r = relOf(npc);
704:   const ch = [{ id:'talk', label:'TALK' }, { id:'rain', label:'TALK ABOUT THE RAIN' }];
705:   ch.push({ id:'city', label:'ASK ABOUT THE CITY' });
706:   ch.push({ id:'rumor', label:'ASK ABOUT RUMORS' });
707:   if (r.met) ch.push({ id:'compliment', label:'COMPLIMENT' });
708:   if (npc.romanceable && (npc.age || 0) >= 18) {
