723: function dialogueChoice(npc, ch) {
724:   const r = relOf(npc);
725:   const id = ch.id;
726:   audio.ui();
727:   if (id === 'bye') { closeDialogue(); return; }
728:   if (id === 'talk') {
729:     const text = r.affinity > 20
730:       ? ['“I was wondering when you’d come by.”', '“You’re becoming a regular. That’s either good or terminal.”', 'They tell you a small, true thing about their day.'][Math.floor(Math.random()*3)]
731:       : ['They talk about work, the weather, the price of everything.', 'The conversation is ordinary. It feels like a luxury.', '“Not much. Same rain. Same city. Different trouble.”'][Math.floor(Math.random()*3)];
732:     r.affinity = clamp(r.affinity + 2, 0, 100); r.trust = clamp(r.trust + 1, 0, 100);
733:     addMemory(npc, 'shared a quiet conversation');
734:     ui.updateDialogueText(text); refreshDialogueChoices(npc); return;
735:   }
736:   if (id === 'rain') {
737:     const text = npcLine(npc, 'weird') && state.weirdness > .35
738:       ? npcLine(npc, 'weird')
739:       : ['“It’s Bellingham. Rain is the local language.”', '“You get used to it. Then you get weird about it.”', '“I like the rain. It makes the city feel honest.”'][Math.floor(Math.random()*3)];
740:     r.affinity = clamp(r.affinity + 1, 0, 100);
741:     ui.updateDialogueText(text); refreshDialogueChoices(npc); return;
742:   }
743:   if (id === 'city') {
744:     ui.updateDialogueText(npcLine(npc, 'city') || '“It’s a city. It has opinions about itself.”');
745:     refreshDialogueChoices(npc); return;
746:   }
747:   if (id === 'rumor') {
748:     let text = npcLine(npc, 'rumor') || '“Rumors are just weather with better marketing.”';
749:     if (state.quest.stage >= 3) text += ' They glance at the nearest streetlight like it might be recording.';
750:     state.weirdness = clamp(state.weirdness + .004, 0, 1);
751:     world.setWeirdness(state.weirdness);
752:     ui.updateDialogueText(text); refreshDialogueChoices(npc); return;
753:   }
754:   if (id === 'compliment') {
755:     r.affinity = clamp(r.affinity + 5, 0, 100); r.mood = r.mood;
756:     state.player.mood = clamp(state.player.mood + 3, 0, 100);
757:     ui.updateDialogueText(['They try not to smile. They fail.', '“Careful. I’m susceptible to that.”', '“You’re not bad yourself. For someone who smells like the bay.”'][Math.floor(Math.random()*3)]);
758:     refreshDialogueChoices(npc); return;
759:   }
760:   if (id === 'flirt') {
761:     if ((npc.age || 0) < 18) { ui.updateDialogueText('They step back. “No.” The conversation is over.'); return; }
762:     if (r.affinity < 10) {
763:       ui.updateDialogueText('They give you a look that could refrigerate a beer. “Let’s not.”');
764:       r.grudge = clamp(r.grudge + 2, 0, 100);
765:     } else {
766:       r.romance = clamp(r.romance + 6, 0, 100); r.affinity = clamp(r.affinity + 4, 0, 100);
767:       r.status = statusFor(r); addMemory(npc, 'flirted and meant it');
768:       ui.updateDialogueText(['They hold your gaze a beat too long. “Smooth. Suspiciously smooth.”', '“You’re trouble,” they say, and do not move away.', 'The rain gets between you. Neither of you steps back.'][Math.floor(Math.random()*3)]);
769:     }
770:     refreshDialogueChoices(npc); return;
771:   }
772:   if (id === 'gift') {
773:     const gift = state.inventory.find(i => ITEMS[i.id]?.type === 'gift');
774:     if (!gift) { ui.updateDialogueText('You have nothing to give but the truth. They can tell.'); return; }
775:     removeItem(gift.id, 1);
776:     r.affinity = clamp(r.affinity + 12, 0, 100); r.romance = clamp(r.romance + 5, 0, 100); r.status = statusFor(r);
777:     addMemory(npc, `received ${ITEMS[gift.id].name}`);
778:     ui.updateDialogueText(`You give them the ${ITEMS[gift.id].name}. ${npc.name.split(' ')[0]} turns it over once, like it might be a key. “Oh.”`);
779:     refreshDialogueChoices(npc); return;
780:   }
781:   if (id === 'date') {
782:     if (r.affinity < 20) { ui.updateDialogueText('“Maybe when I know you better.”'); return; }
783:     r.dates++; r.romance = clamp(r.romance + 10, 0, 100); r.affinity = clamp(r.affinity + 8, 0, 100);
784:     r.status = statusFor(r); addMemory(npc, 'went on a date');
785:     state.player.mood = clamp(state.player.mood + 16, 0, 100);
786:     state.player.money = Math.max(0, state.player.money - 35);
787:     state.time.minutes += 150;
788:     state.player.energy = clamp(state.player.energy - 10, 0, 100);
789:     closeDialogue();
790:     gameMode = 'modal';
791:     ui.cinematic('A NIGHT OFF', 'THE CITY, BRIEFLY KIND', 'You eat something warm. You walk until the rain stops being an emergency. Neither of you checks your phone.');
792:     setTimeout(() => {
