116:   s.flags.bossesDefeated = Array.isArray(s.flags.bossesDefeated) ? s.flags.bossesDefeated : [];
117:   s.flags.artifacts = Array.isArray(s.flags.artifacts) ? s.flags.artifacts : [];
118:   s.flags.endings = Array.isArray(s.flags.endings) ? s.flags.endings : [];
119:   initRelationships(s);
120:   return s;
