270: function loop(now) {
271:   const rawDt = Math.min(.06, (now - lastFrame) / 1000 || .016);
272:   lastFrame = now;
273:   elapsed += rawDt;
274:   if (gameMode === 'menu') {
275:     world.update(rawDt, elapsed, { x:player.x, y:0, z:player.z }, state);
276:     if (!isTouch) {
277:       camera.position.set(player.x, 1.68 + Math.sin(elapsed * .5) * .015, player.z);
278:       camera.rotation.order = 'YXZ';
279:       camera.rotation.y = player.yaw + Math.sin(elapsed * .09) * .12;
280:       camera.rotation.x = -.03;
281:     }
282:     ui.updateHUD(false);
283:     renderer.render(scene, camera);
284:     requestAnimationFrame(loop);
285:     return;
286:   }
287:   const paused = ['dialogue','panel','map','settings','pause','timing','ending','modal'].includes(gameMode);
288:   if (!paused) {
289:     if (gameMode === 'play') {
290:       updateSimulation(rawDt);
291:       player.update(rawDt, elapsed);
292:       npcs.update(rawDt, { x:player.x, y:player.y, z:player.z }, elapsed);
293:       updateInteraction();
294:       updateStoryVisibility();
295:       updateWeather(rawDt);
296:       updateEvents(rawDt);
297:     } else if (gameMode === 'combat') {
298:       player.update(rawDt, elapsed);
299:       combat.update(rawDt);
300:       npcs.update(rawDt, { x:player.x, y:player.y, z:player.z }, elapsed);
301:     }
302:     world.update(rawDt, elapsed, { x:player.x, y:player.y, z:player.z }, state);
303:     updateObjectiveBeacon(rawDt);
304:     audio.update(rawDt);
305:     ui.updateHUD(false);
306:     if (gameMode === 'play') {
307:       if (now - lastAutoSave > 30000) { lastAutoSave = now; saveGame(true); }
308:     }
309:   } else {
310:     world.update(rawDt * .2, elapsed, { x:player.x, y:player.y, z:player.z }, state);
311:     audio.update(rawDt * .2);
312:   }
313:   if (timingGame) updateTiming(rawDt);
314:   renderer.render(scene, camera);
315:   requestAnimationFrame(loop);
316: }
