385: function refreshQuest() {
386:   if (!state || !ui) return;
387:   const q = QUESTS[state.quest.stage] || QUESTS[0];
388:   let obj = q.objective;
389:   let targetPos = null;
390:   if (q.target) {
391:     const b = BUSINESSES.find(x => x.id === q.target);
392:     if (b) targetPos = { x:b.entry.x, z:b.entry.z };
393:   }
394:   if (state.quest.stage === 2) targetPos = { x:world.arena.x, z:world.arena.z + 20 };
395:   if (state.quest.stage >= 3 && state.quest.stage !== 4 && state.quest.stage !== 5) {
396:     targetPos = player && Math.hypot(player.x - world.arena.x, player.z - world.arena.z) < 60
397:       ? { x:world.arena.x + 15, z:world.arena.z - 15 }
398:       : { x:BUSINESSES.find(b=>b.id==='terminal9').entry.x, z:BUSINESSES.find(b=>b.id==='terminal9').entry.z };
399:   }
400:   if (state.quest.stage === 3) {
401:     const wins = Math.max(0, (state.flags.bossesDefeated?.length || 0) - 1);
402:     obj = wins >= 3 ? 'Return to Terminal 9. Something has changed.' : `Defeat ${3 - wins} more challenger${3-wins===1?'':'s'} at Terminal 9.`;
403:     targetPos = player && Math.hypot(player.x - world.arena.x, player.z - world.arena.z) < 60
404:       ? { x:world.arena.x + 15, z:world.arena.z - 15 } : { x:190, z:-192 };
405:   }
406:   if (state.quest.stage === 4) {
407:     targetPos = { x:-112, z:180 };
408:     obj = world.weather === 'storm' ? 'Find the yellow raincoat at Boulevard Park.' : 'Wait for the storm. The forecast is wrong on purpose.';
409:   }
410:   if (state.quest.stage === 5) targetPos = { x:300, z:54 };
411:   if (state.quest.stage === 6) {
412:     targetPos = player && Math.hypot(player.x - world.arena.x, player.z - world.arena.z) < 60
413:       ? { x:world.arena.x + 15, z:world.arena.z - 15 } : { x:190, z:-192 };
414:   }
415:   if (state.quest.stage === 7) { targetPos = null; obj = 'Decide what Bellingham becomes.'; }
416:   objectiveTarget = targetPos;
417:   let progress = 0;
418:   if (state.quest.stage === 0) progress = state.flags.workedShift ? 1 : 0;
419:   if (state.quest.stage === 1) progress = state.flags.busRide ? 1 : 0;
420:   if (state.quest.stage === 2) progress = state.flags.bossesDefeated?.includes('barista') ? 1 : 0;
421:   if (state.quest.stage === 3) progress = clamp(((state.flags.bossesDefeated?.length || 0) - 1) / 3, 0, 1);
422:   if (state.quest.stage === 4) progress = state.flags.raincoatFound ? 1 : 0;
423:   if (state.quest.stage === 5) progress = state.flags.mirrorDefeated ? 1 : 0;
424:   if (state.quest.stage === 6) progress = state.flags.futureDefeated ? 1 : 0;
425:   ui.setObjective({ chapter:q.chapter, title:q.title, objective:obj, targetPos, progress });
426:   ui.updateHUD(true);
427: }
