811:     closeDialogue();
812:     gameMode = 'modal';
813:     ui.modal({
814:       kicker:'CONSENT · ADULTS ONLY', title:'SPEND THE NIGHT?',
815:       body:`<p>${esc(npc.name)} asks if you want to come back to their place. You both agree, clearly, without pressure.</p><p class="modal-quote">The rest happens off-screen. This story fades to black.</p>`,
816:       actions:[{label:'YES, TONIGHT', id:'yes', primary:true}, {label:'NOT TONIGHT', id:'no'}],
817:       onAction:(a) => {
