917: function removeItem(id, qty = 1) {
918:   const it = state.inventory.find(i => i.id === id);
919:   if (!it) return false;
920:   it.qty -= qty;
921:   if (it.qty <= 0) state.inventory = state.inventory.filter(i => i !== it);
922:   return true;
923: }
