930: function useItem(id) {
931:   const item = ITEMS[id];
932:   if (!item) return;
933:   const inv = state.inventory.find(i => i.id === id);
934:   if (!inv) return;
935:   const p = state.player;
936:   if (item.effects) {
937:     for (const [k, v] of Object.entries(item.effects)) p[k] = clamp((p[k] || 0) + v, 0, k === 'intoxication' ? 100 : 100);
938:   }
939:   removeItem(id, 1);
940:   if (id === 'pills') {
941:     p.health = clamp(p.health - 12, 0, 100); p.mood = clamp(p.mood + 20, 0, 100);
942:     state.flags.darkRep = (state.flags.darkRep || 0) + 1;
943:     ui.toast('<b>UNLABELED</b> · Your heart does a drum fill. The room breathes with you.', 'warn');
944:   }
945:   if (id === 'joint') ui.toast('<b>CHUCKANUT GREEN</b> · The rain sounds like applause.', '');
946:   ui.toast(`<b>USED</b> · ${item.name}.`, '');
947:   audio.cash();
948:   saveGame(true);
949:   if (ui.panelOpen) openPhone('bag');
