408:     const mat = new THREE.MeshBasicMaterial({ color, transparent:true, opacity:.8, side:THREE.DoubleSide, depthWrite:false, blending:THREE.AdditiveBlending });
409:     const mesh = new THREE.Mesh(geo, mat); mesh.rotation.x = -Math.PI/2; mesh.position.copy(pos); this.scene.add(mesh);
410:     this.rings.push({ mesh, life:duration, max:duration, inner });
411:   }
