397:     for (let i = 0; i < count; i++) { arr[i*3]=0; arr[i*3+1]=0; arr[i*3+2]=0; }
398:     geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
399:     const mat = new THREE.PointsMaterial({ color, size:.11, transparent:true, opacity:1, depthWrite:false, blending:THREE.AdditiveBlending });
400:     const mesh = new THREE.Points(geo, mat); mesh.position.copy(pos); this.scene.add(mesh);
401:     const vel = [];
402:     for (let i = 0; i < count; i++) vel.push(new THREE.Vector3((Math.random()-.5)*8, Math.random()*6, (Math.random()-.5)*8));
403:     this.impactParticles.push({ mesh, vel, life:1 });
404:   }
