465:   update(dt) {
466:     if (!this.active) return;
467:     this.updateUI();
468:     if (this.endResult) {
469:       this.endTimer -= dt;
470:       this.slowmo = lerp(this.slowmo, 1, dt * 2);
471:       this.updateEffects(dt);
472:       if (this.endTimer <= 0) this.finishCombat();
473:       return;
474:     }
475:     if (this.finisherActive) {
476:       this.updateEffects(dt * .2);
477:       return;
478:     }
479:     const scaled = dt * this.slowmo;
480:     for (const k in this.cooldowns) this.cooldowns[k] = Math.max(0, this.cooldowns[k] - dt);
481:     this.iframe = Math.max(0, this.iframe - dt);
482:     this.enemyStun = Math.max(0, this.enemyStun - scaled);
483:     this.playerStun = Math.max(0, this.playerStun - dt);
484:     this.comboTimer -= dt;
485:     if (this.comboTimer <= 0) this.combo = 0;
486:     this.stamina = clamp(this.stamina + dt * 11, 0, 100);
487:     this.state.player.stamina = this.stamina;
488:     this.state.player.health = this.playerHP;
489:     this.special = clamp(this.special + dt * .65, 0, 100);
490:     this.player.blocking = this.blocking;
491:     if (this.blocking) this.blockTime += dt; else this.blockTime = 0;
492: 
493:     // player movement is normal; keep facing target when close
494:     if (this.distance < 5.5) {
495:       const targetYaw = Math.atan2(-(this.enemyPos.x - this.player.x), -(this.enemyPos.z - this.player.z));
496:       let diff = ((targetYaw - this.player.yaw + Math.PI * 3) % TAU) - Math.PI;
497:       if (Math.abs(diff) > .35) this.player.yaw += diff * dt * .8;
498:     }
499:     // clamp to arena
500:     if (this.arenaFight) {
501:       const a = this.world.arena;
502:       const d = Math.hypot(this.player.x - a.x, this.player.z - a.z);
503:       if (d > 11) {
504:         const ang = Math.atan2(this.player.z - a.z, this.player.x - a.x);
505:         this.player.x = a.x + Math.cos(ang) * 10.7; this.player.z = a.z + Math.sin(ang) * 10.7;
506:       }
507:     }
508: 
509:     // enemy AI
510:     if (this.enemy && !this.endResult) {
511:       const npc = this.enemy;
512:       const ex = npc.group.position.x, ez = npc.group.position.z;
513:       const dx = this.player.x - ex, dz = this.player.z - ez;
514:       const dist = Math.hypot(dx, dz) || .001;
515:       npc.facing = Math.atan2(dx, dz);
516:       npc.group.rotation.y = npc.facing;
517:       npc.group.position.y = 0;
518:       if (this.enemyState !== 'attack' && this.enemyState !== 'special' && this.enemyState !== 'stagger' && this.enemyState !== 'counter') {
519:         this.enemyTimer -= scaled;
520:         this.enemyCooldown -= scaled;
521:         this.enemySpecialCooldown -= scaled;
522:         // movement
523:         let moveSpeed = (this.boss ? 2.1 : 1.6) * (this.boss?.speed || 1);
524:         if (this.boss?.id === 'barista') moveSpeed *= 1.25;
525:         if (this.boss?.id === 'oldman') moveSpeed *= .7;
526:         if (dist > 2.7) {
527:           const nx = ex + dx / dist * moveSpeed * scaled;
528:           const nz = ez + dz / dist * moveSpeed * scaled;
529:           if (!this.world.isBlocked(nx, nz, .4)) { npc.group.position.x = nx; npc.group.position.z = nz; }
530:         } else if (dist < 1.65) {
531:           npc.group.position.x -= dx / dist * moveSpeed * .55 * scaled;
532:           npc.group.position.z -= dz / dist * moveSpeed * .55 * scaled;
533:         } else {
534:           const side = Math.sin(this.enemyTimer * 1.7) * .55;
535:           const nx = ex + (-dz / dist) * side * scaled, nz = ez + (dx / dist) * side * scaled;
536:           if (!this.world.isBlocked(nx, nz, .4)) { npc.group.position.x = nx; npc.group.position.z = nz; }
537:         }
538:         npc.x = npc.group.position.x; npc.z = npc.group.position.z;
539:         if (this.enemySpecialCooldown <= 0 && this.boss) {
540:           this.enemySpecialCooldown = 6 + Math.random() * 4;
541:           this.triggerBossSpecial();
542:         } else if (this.enemyCooldown <= 0 && dist < 3.4) {
543:           this.enemyState = 'windup';
