793:       ui.modal({
794:         kicker:'RELATIONSHIP', title:'A GOOD NIGHT',
795:         body:`<p>You and ${esc(npc.name)} spend two hours at ${['Boulevard Park','the marina','a noodle place that is somehow still open','the bookstore after hours'][Math.floor(Math.random()*4)]}. It is not cinematic. It is better.</p><p class="modal-quote">“Same time next week?” they ask.<br>You say yes before you can calculate anything.</p>`,
796:         actions:[{label:'CONTINUE', id:'ok', primary:true}],
797:         onAction:() => { ui.closeModal(); gameMode = 'play'; refreshDialogueChoices(npc); }
798:       });
799:     }, 1500);
800:     return;
