66:   start(npc, opts = {}) {
67:     if (this.active || !npc) return false;
68:     this.active = true;
69:     this.enemy = npc;
70:     this.boss = opts.boss || null;
71:     this.arenaFight = !!opts.arena;
72:     this.onEnd = opts.onEnd || null;
73:     const boss = this.boss;
74:     this.enemyMax = boss ? boss.hp : 75 + Math.floor((this.state.player.level || 1) * 7);
75:     this.enemyHP = this.enemyMax;
76:     this.playerMax = 100 + ((this.state.player.level || 1) - 1) * 6;
77:     this.playerHP = clamp(this.state.player.health || this.playerMax, 1, this.playerMax);
78:     this.state.player.health = this.playerHP;
79:     this.stamina = this.state.player.stamina || 100;
80:     this.special = 0;
81:     this.combo = 0; this.comboTimer = 0;
82:     this.enemyState = 'approach';
83:     this.enemyTimer = 1.1;
84:     this.enemyCooldown = 1.6;
85:     this.enemySpecialCooldown = 6.5;
86:     this.enemyHits = 0;
87:     this.blocking = false; this.blockTime = 0; this.iframe = 0;
88:     this.slowmo = 1; this.finisherActive = false;
89:     this.endResult = null; this.endTimer = 0;
90:     this.enemyStun = 0; this.playerStun = 0;
91:     this.audio.setFight(true);
92:     this.ui.setCombat(true);
93:     this.ui.updateCombat(this.combatData());
94:     this.ui.showCallout(boss ? boss.title : 'STREET FIGHT');
95:     this.ui.toast(boss ? `${boss.name} // ${boss.style}` : `${npc.name} wants to throw hands.`, boss ? 'warn' : '');
96:     this.camera.fov = 66; this.camera.updateProjectionMatrix();
97:     // position
98:     const f = this.player.getForward();
99:     const dist = this.arenaFight ? 4.2 : 3.1;
100:     let tx = this.player.x + f.x * dist, tz = this.player.z + f.z * dist;
101:     if (this.world.isBlocked(tx, tz, .5)) { tx = this.player.x - f.x * dist; tz = this.player.z - f.z * dist; }
102:     npc.group.position.set(tx, 0, tz);
103:     npc.x = tx; npc.z = tz;
104:     npc.facing = Math.atan2(this.player.x - tx, this.player.z - tz);
105:     npc.group.rotation.y = npc.facing;
106:     npc.combat = true;
107:     npc.targetX = tx; npc.targetZ = tz;
108:     this.npcs.faceEachOther(npc, { x:this.player.x, z:this.player.z });
109:     this.player.yaw = Math.atan2(-(tx - this.player.x), -(tz - this.player.z));
110:     this.player.pitch = -.04;
111:     // style-specific
112:     this.style = STYLES[this.state.player.style] || STYLES.street;
113:     this.ui.setStyle(this.state.player.style);
114:     this.spawnRing(new THREE.Vector3(tx, .2, tz), boss ? new THREE.Color(boss.accent) : new THREE.Color(0xffb35c), 1.6, .6);
115:     this.audio.special();
116:     return true;
117:   }
