122:       enemyHP:this.enemyHP, enemyMax:this.enemyMax, stamina:this.stamina,
123:       special:this.special, combo:this.combo, enemyName:this.boss ? this.boss.name : (this.enemy?.name || 'UNKNOWN'),
124:       enemySub:this.boss ? this.boss.style : (this.enemy?.tag || 'STREET'),
125:       playerName:this.state.player.name || 'ROOKIE',
126:       style:this.style?.name || 'STREET',
127:       canFinish:this.enemyHP > 0 && this.enemyHP <= this.enemyMax * .2 && this.special >= 50
128:     };
