179:   dodge() {
180:     if (!this.active || this.endResult || this.finisherActive) return;
181:     if (this.cooldowns.dodge > 0 || this.stamina < 9 || this.playerStun > 0) return;
182:     this.cooldowns.dodge = .85;
183:     this.stamina -= 9;
184:     const reflex = this.state.player.reflex || 1;
185:     this.iframe = .46 + Math.min(.22, reflex * .03);
186:     this.audio.dodge?.();
187:     const f = this.player.getForward();
188:     const side = Math.random() < .5 ? 1 : -1;
189:     const tries = [
190:       [this.player.x - f.z * side * 2.3, this.player.z + f.x * side * 2.3],
191:       [this.player.x + f.z * side * 2.3, this.player.z - f.x * side * 2.3],
192:       [this.player.x - f.x * 2.1, this.player.z - f.z * 2.1]
193:     ];
194:     for (const [nx, nz] of tries) {
195:       if (!this.world.isBlocked(nx, nz, this.player.radius)) { this.player.x = nx; this.player.z = nz; break; }
196:     }
197:     this.ui.showCallout('DODGE');
