205:     this.stamina -= 14;
206:     const kind = this.arenaFight ? 'ring post' : ['trash can','loose brick','traffic cone','wet newspaper'][Math.floor(Math.random()*4)];
207:     this.ui.showCallout('ENVIRONMENT // ' + kind.toUpperCase());
208:     this.player.animateAttack('punch');
209:     setTimeout(() => {
210:       if (!this.active) return;
211:       if (this.distance < 4.2) {
212:         this.hitEnemy(11 + Math.floor(Math.random()*7), 'ENVIRONMENT', true);
213:         this.enemyStun = .7;
214:         this.audio.impact?.(1); this.audio.hit(1);
215:         const pos = new THREE.Vector3(this.enemyPos.x, 1.2, this.enemyPos.z);
216:         this.spawnImpact(pos, new THREE.Color(0xffb35c), 20);
