247:   hitEnemy(dmg, label, heavy = false) {
248:     if (!this.active || this.enemyHP <= 0) return;
249:     const rounded = Math.round(dmg);
250:     this.enemyHP = Math.max(0, this.enemyHP - rounded);
251:     this.npcs.playHit(this.enemy);
252:     this.ui.damageNumber(rounded, this.enemyPos, this.camera);
253:     if (heavy) this.enemyStun = Math.max(this.enemyStun, .5);
254:     if (this.enemyHP <= 0) this.win();
255:   }
