179:   dodge() {
180:     if (!this.active || this.endResult || this.finisherActive) return;
181:     if (this.cooldowns.dodge > 0 || this.stamina < 9 || this.playerStun > 0) return;
182:     this.cooldowns.dodge = .85;
183:     this.stamina -= 9;
