221:   tryHit(type) {
222:     const inRange = type === 'kick' ? this.distance < 3.15 : this.distance < 2.55;
223:     if (!inRange) return;
224:     let dmg = type === 'kick' ? 11 : 7;
225:     dmg += (this.state.player.strength || 1) * 1.4;
226:     if (this.state.player.style === 'muay' && type === 'kick') dmg *= 1.35;
227:     if (this.state.player.style === 'street') dmg *= 1.08;
228:     if (this.enemyStun > 0) dmg *= 1.25;
229:     if (this.enemyState === 'block') dmg *= .25;
230:     const comboMult = 1 + Math.min(this.combo, 8) * .055;
231:     dmg *= comboMult;
232:     this.hitEnemy(dmg, type.toUpperCase());
233:     this.special = clamp(this.special + (type === 'kick' ? 8 : 5), 0, 100);
234:     this.combo++;
235:     this.comboTimer = 2.2;
236:     this.player.addShake(type === 'kick' ? .24 : .14);
237:     this.audio.hit(type === 'kick' ? 1.25 : .8);
238:     const pos = new THREE.Vector3(this.enemyPos.x, 1.25, this.enemyPos.z);
239:     this.spawnImpact(pos, new THREE.Color(type === 'kick' ? 0xffb35c : 0x7fe3d2), type === 'kick' ? 16 : 10);
240:     if (this.combo >= 3) this.ui.showCombo(this.combo);
241:     if (this.boss?.id === 'student' && this.enemyState === 'counter') {
242:       this.counterPlayer(9);
243:       this.ui.showCallout('RED PEN COUNTER');
244:     }
245:   }
