413:   triggerBossSpecial() {
414:     if (!this.boss || this.endResult) return;
415:     const b = this.boss;
416:     const ability = b.abilities[Math.floor(Math.random() * b.abilities.length)];
417:     this.ui.showCallout(ability.toUpperCase());
418:     this.audio.special();
419:     this.spawnRing(new THREE.Vector3(this.enemyPos.x, .3, this.enemyPos.z), new THREE.Color(b.accent), 1, 1.4);
420:     this.enemyState = 'special';
421:     this.enemyTimer = 1.15;
422:     this.enemyAttack = { type:'boss', ability, damage:b.dmg * 1.5 };
423:     if (b.id === 'raincoat') {
424:       const f = this.player.getForward();
425:       this.enemy.group.position.set(this.player.x - f.x * 2.3, 0, this.player.z - f.z * 2.3);
426:       this.enemy.x = this.enemy.group.position.x; this.enemy.z = this.enemy.group.position.z;
427:     }
428:     if (b.id === 'ferryman') {
429:       const dx = this.enemyPos.x - this.player.x, dz = this.enemyPos.z - this.player.z;
430:       const d = Math.hypot(dx,dz) || 1;
431:       this.player.x += dx / d * 1.5; this.player.z += dz / d * 1.5;
432:       this.player.addShake(.25);
433:     }
434:     if (b.id === 'future' && this.enemyHP < this.enemyMax * .6) this.enemyHP = Math.min(this.enemyMax, this.enemyHP + 8);
435:     if (b.id === 'mayor') this.playerStun = 1.2;
436:     if (b.id === 'hiker') this.playerStun = .8;
437:     if (b.id === 'oldman') this.slowmo = .55;
438:     setTimeout(() => {
439:       if (!this.active || this.endResult) return;
440:       const dist = this.distance;
441:       const blocked = this.blocking;
442:       if (dist < 5.2 || b.id === 'mayor' || b.id === 'ferryman') {
443:         let dmg = b.dmg * (1.1 + Math.random() * .6);
444:         if (blocked) dmg *= .32;
445:         if (this.iframe > 0) dmg = 0;
446:         if (b.id === 'mirror' && this.lastPlayerAttack === 'kick') dmg *= 1.2;
447:         if (b.id === 'student' && this.lastPlayerAttack) dmg *= 1.15;
448:         if (dmg > 0) {
449:           this.playerHP = Math.max(0, this.playerHP - Math.round(dmg));
450:           this.state.player.health = this.playerHP;
451:           this.player.addShake(.7);
452:           this.ui.flashHit();
453:           this.audio.hit(1.2);
454:           this.spawnImpact(new THREE.Vector3(this.player.x, 1.2, this.player.z), new THREE.Color(b.accent), 22);
455:           this.combo = 0;
456:           if (this.playerHP <= 0) this.lose();
457:         } else this.ui.showCallout('DODGED');
458:       }
459:       this.slowmo = 1;
460:       this.enemyState = 'recover';
461:       this.enemyTimer = 1.2;
462:     }, 850);
463:   }
464: 
465:   update(dt) {
466:     if (!this.active) return;
467:     this.updateUI();
468:     if (this.endResult) {
469:       this.endTimer -= dt;
470:       this.slowmo = lerp(this.slowmo, 1, dt * 2);
471:       this.updateEffects(dt);
472:       if (this.endTimer <= 0) this.finishCombat();
473:       return;
474:     }
475:     if (this.finisherActive) {
476:       this.updateEffects(dt * .2);
477:       return;
478:     }
479:     const scaled = dt * this.slowmo;
480:     for (const k in this.cooldowns) this.cooldowns[k] = Math.max(0, this.cooldowns[k] - dt);
481:     this.iframe = Math.max(0, this.iframe - dt);
482:     this.enemyStun = Math.max(0, this.enemyStun - scaled);
483:     this.playerStun = Math.max(0, this.playerStun - dt);
484:     this.comboTimer -= dt;
485:     if (this.comboTimer <= 0) this.combo = 0;
